Para resolver este problema de forma eficiente, podemos fazer a transformação padrão para a métrica de Chebyshev ($L_\infty$). 

A distância quadradônica (Manhattan) entre dois pontos $(X_1, Y_1)$ e $(X_2, Y_2)$ é dada por:
$$|X_1 - X_2| + |Y_1 - Y_2| = \max(|U_1 - U_2|, |V_1 - V_2|)$$
onde definimos $U_i = X_i + Y_i$ e $V_i = X_i - Y_i$.

Dessa forma, o problema se reduz ao clássico problema de **2-centro em $L_\infty$**: cobrir um conjunto de $N$ pontos com dois quadrados de lado $D$ alinhados aos eixos coordenados, minimizando o lado $D$.

Podemos realizar uma **busca binária** no valor ótimo de $D \in [0, 2 \cdot 10^9]$. Para verificar se um dado $D$ é suficiente:
- Seja $U_{\min}, U_{\max}, V_{\min}, V_{\max}$ os limites da menor caixa envolvente de todos os pontos.
- Se o conjunto de pontos pode ser coberto por dois quadrados de lado $D$, é suficiente e necessário testar duas configurações simétricas onde um dos quadrados cobre um canto da caixa envolvente:
  1. O primeiro quadrado cobre o canto sudoeste: $[U_{\min}, U_{\min} + D] \times [V_{\min}, V_{\min} + D]$.
  2. O primeiro quadrado cobre o canto noroeste: $[U_{\min}, U_{\min} + D] \times [V_{\max} - D, V_{\max}]$.
- Para cada configuração, coletamos os pontos que **não** estão cobertos pelo primeiro quadrado e verificamos se todos eles cabem em um único quadrado de lado $D$, ou seja, se $\max(U_{\text{rest}}) - \min(U_{\text{rest}}) \le D$ e $\max(V_{\text{rest}}) - \min(V_{\text{rest}}) \le D$.

Como $N \le 300\,000$, a verificação leva tempo $O(N)$ e a busca binária realiza cerca de 31 passos, resultando em uma complexidade total de $O(N \log(\text{MAX}))$, perfeitamente dentro do limite de tempo.

Abaixo está a solução completa em Java:

```java
import java.io.InputStream;
import java.io.IOException;

public class Main {

    static int N;
    static long[] U;
    static long[] V;

    static long minU, maxU, minV, maxV;

    static boolean check(long D) {
        // Se um único quadrado cobre todos os pontos
        if (maxU - minU <= D && maxV - minV <= D) {
            return true;
        }

        // Opção 1: Q1 cobre o canto inferior esquerdo (SW)
        // Q1 = [minU, minU + D] x [minV, minV + D]
        long restMinU = Long.MAX_VALUE, restMaxU = Long.MIN_VALUE;
        long restMinV = Long.MAX_VALUE, restMaxV = Long.MIN_VALUE;
        boolean hasRest = false;

        long limU1 = minU + D;
        long limV1 = minV + D;

        for (int i = 0; i < N; i++) {
            long u = U[i];
            long v = V[i];
            if (u > limU1 || v > limV1) {
                if (u < restMinU) restMinU = u;
                if (u > restMaxU) restMaxU = u;
                if (v < restMinV) restMinV = v;
                if (v > restMaxV) restMaxV = v;
                hasRest = true;
            }
        }

        if (!hasRest || (restMaxU - restMinU <= D && restMaxV - restMinV <= D)) {
            return true;
        }

        // Opção 2: Q1 cobre o canto superior esquerdo (NW)
        // Q1 = [minU, minU + D] x [maxV - D, maxV]
        restMinU = Long.MAX_VALUE;
        restMaxU = Long.MIN_VALUE;
        restMinV = Long.MAX_VALUE;
        restMaxV = Long.MIN_VALUE;
        hasRest = false;

        long limV2 = maxV - D;

        for (int i = 0; i < N; i++) {
            long u = U[i];
            long v = V[i];
            if (u > limU1 || v < limV2) {
                if (u < restMinU) restMinU = u;
                if (u > restMaxU) restMaxU = u;
                if (v < restMinV) restMinV = v;
                if (v > restMaxV) restMaxV = v;
                hasRest = true;
            }
        }

        if (!hasRest || (restMaxU - restMinU <= D && restMaxV - restMinV <= D)) {
            return true;
        }

        return false;
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);
        N = fs.nextInt();

        long[] X = new long[N];
        for (int i = 0; i < N; i++) {
            X[i] = fs.nextLong();
        }

        U = new long[N];
        V = new long[N];

        minU = Long.MAX_VALUE;
        maxU = Long.MIN_VALUE;
        minV = Long.MAX_VALUE;
        maxV = Long.MIN_VALUE;

        for (int i = 0; i < N; i++) {
            long y = fs.nextLong();
            long u = X[i] + y;
            long v = X[i] - y;
            U[i] = u;
            V[i] = v;

            if (u < minU) minU = u;
            if (u > maxU) maxU = u;
            if (v < minV) minV = v;
            if (v > maxV) maxV = v;
        }

        long low = 0;
        long high = 2000000000L;
        long ans = high;

        while (low <= high) {
            long mid = (low + high) >>> 1;
            if (check(mid)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }

        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int len = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private int readByte() throws IOException {
            if (ptr >= len) {
                ptr = 0;
                len = in.read(buffer);
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        public int nextInt() throws IOException {
            return (int) nextLong();
        }

        public long nextLong() throws IOException {
            int c = readByte();
            while (c <= ' ' && c != -1) {
                c = readByte();
            }
            if (c == -1) return -1;
            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = readByte();
            }
            long res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = readByte();
            }
            return neg ? -res : res;
        }
    }
}
