    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int head = 0;
        private int tail = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private byte read() throws IOException {
            if (head >= tail) {
                head = 0;
                tail = in.read(buffer, 0, buffer.length);
                if (tail <= 0) return -1;
            }
            return buffer[head++];
        }

        public int nextInt() throws IOException {
            byte c = read();
            while (c <= ' ') {
                if (c == -1) return -1;
                c = read();
            }
            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = read();
            }
            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = read();
            }
            return neg ? -res : res;
        }
    }

    static int n;
    static long[] u;
    static long[] v;
    static long uMin, uMax, vMin, vMax;

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        n = scanner.nextInt();
        if (n <= 0) {
            return;
        }

        long[] x = new long[n];
        for (int i = 0; i < n; i++) {
            x[i] = scanner.nextInt();
        }

        u = new long[n];
        v = new long[n];

        uMin = Long.MAX_VALUE;
        uMax = Long.MIN_VALUE;
        vMin = Long.MAX_VALUE;
        vMax = Long.MIN_VALUE;

        for (int i = 0; i < n; i++) {
            long y = scanner.nextInt();
            long ui = x[i] + y;
            long vi = x[i] - y;
            u[i] = ui;
            v[i] = vi;
            if (ui < uMin) uMin = ui;
            if (ui > uMax) uMax = ui;
            if (vi < vMin) vMin = vi;
            if (vi > vMax) vMax = vi;
        }

        long low = 0;
        long high = Math.max(uMax - uMin, vMax - vMin);
        long ans = high;

        while (low <= high) {
            long mid = low + (high - low) / 2;
            if (check(mid)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }

        System.out.println(ans);
    }

    private static boolean check(long d) {
        if (uMax - uMin <= d && vMax - vMin <= d) {
            return true;
        }

        // Testar os 4 cantos possíveis para o primeiro quadrado
        if (checkCorner(uMin, uMin + d, vMin, vMin + d, d)) return true;
        if (checkCorner(uMin, uMin + d, vMax - d, vMax, d)) return true;
        if (checkCorner(uMax - d, uMax, vMin, vMin + d, d)) return true;
        if (checkCorner(uMax - d, uMax, vMax - d, vMax, d)) return true;

        return false;
    }

    private static boolean checkCorner(long u1, long u2, long v1, long v2, long d) {
        long outUMin = Long.MAX_VALUE;
        long outUMax = Long.MIN_VALUE;
        long outVMin = Long.MAX_VALUE;
        long outVMax = Long.MIN_VALUE;

        for (int i = 0; i < n; i++) {
            long ui = u[i];
            long vi = v[i];
            if (ui < u1 || ui > u2 || vi < v1 || vi > v2) {
                if (ui < outUMin) outUMin = ui;
                if (ui > outUMax) outUMax = ui;
                if (vi < outVMin) outVMin = vi;
                if (vi > outVMax) outVMax = vi;
            }
        }

        // Se nenhum ponto ficou de fora, ou se os pontos de fora cabem em uma caixa d x d
        if (outUMin == Long.MAX_VALUE) {
            return true;
        }

        return (outUMax - outUMin <= d) && (outVMax - outVMin <= d);
    }
